    fun getByCategory(category: String): List<AuditQuestion> =
        all.filter { it.category == category }

    val categories = listOf("1С", "2С", "3С", "4С", "5С")

    fun maxScoreForCategory(category: String): Int =
        getByCategory(category).size * 3

    fun passingScore(category: String): Int =
        if (category == "5С") 12 else 30
